-- Applied 2026-09-30 to rlfxnjbqxbozjdzkbwlz.
-- Data-only update: retains identity, title, scope and teacher confirmation state.
-- Only updates original eight-unit assignments without recorded unit progress.
-- Rico already has four canonical classes and is preserved.
update public.seminar_student_projects p set sprints=case project_slug when 'arango-web-resilience-defense-lab' then '[{"n":1,"title":"1 · Alcance y línea base","goal":"Elige el caso que corresponde al proyecto y documenta activo, amenaza y criterio de éxito. Descarga el laboratorio, lee README.md y revisa docker-compose.yml para identificar puertos y servicios. Inicia el entorno y conserva configuración y línea base.","deliverable":"Diagrama del entorno, alcance autorizado, configuración y registro de línea base.","theory":["Activo, amenaza, control y evidencia forman un modelo de defensa. Define éxito para peticiones legítimas y para el escenario de abuso.","Trabaja con el laboratorio local provisto. Los casos disponibles son resiliencia HTTP, abuso de autenticación, control de acceso y XSS almacenado."],"workshop":["Elige el caso que corresponde al proyecto y documenta activo, amenaza y criterio de éxito.","Descarga el laboratorio, lee README.md y revisa docker-compose.yml para identificar puertos y servicios.","Inicia el entorno y conserva configuración y línea base."],"tests":["Verifica que los servicios arrancan y una petición legítima funciona.","Registra código HTTP, latencia, fecha y condición de prueba; elimina secretos de las evidencias."],"gate":"El entorno local funciona y la condición de prueba es reproducible.","theory_href":"https://juanperez238421-cpu.github.io/ijr-estadistica-11-2026/seminario-projects/route.html?project=cyber#stage-1","workshop_href":"https://juanperez238421-cpu.github.io/ijr-estadistica-11-2026/seminario-projects/route.html?project=cyber#stage-1"},{"n":2,"title":"2 · Reproducir y explicar el caso","goal":"Sigue el caso correspondiente de la biblioteca, usando exclusivamente el entorno local. Inspecciona la petición, HTML, código del servicio y logs para localizar el control ausente. Fija entrada, duración y condiciones; registra una ejecución previa a la defensa.","deliverable":"Petición o fixture, logs saneados, resultado previo y explicación de la causa.","theory":["Un hallazgo debe enlazar entrada, comportamiento observado y causa. Un error aislado no demuestra una vulnerabilidad.","Para resiliencia, mide también disponibilidad del tráfico legítimo; para autorización, prueba acceso permitido y denegado."],"workshop":["Sigue el caso correspondiente de la biblioteca, usando exclusivamente el entorno local.","Inspecciona la petición, HTML, código del servicio y logs para localizar el control ausente.","Fija entrada, duración y condiciones; registra una ejecución previa a la defensa."],"tests":["Comprueba que el caso produce el comportamiento descrito y que puedes repetirlo.","Añade una prueba legítima de control con la misma configuración."],"gate":"La evidencia distingue el caso de abuso de una petición legítima y permite reproducirlo.","theory_href":"https://juanperez238421-cpu.github.io/ijr-estadistica-11-2026/seminario-projects/route.html?project=cyber#stage-2","workshop_href":"https://juanperez238421-cpu.github.io/ijr-estadistica-11-2026/seminario-projects/route.html?project=cyber#stage-2"},{"n":3,"title":"3 · Implementar la defensa","goal":"Implementa el control del caso elegido y documenta el archivo y la decisión técnica. Reinicia o reconstruye los servicios afectados siguiendo el README. Repite exactamente el escenario anterior y una petición legítima.","deliverable":"Diff/commit, configuración y tabla antes/después con las mismas condiciones.","theory":["El control se aplica en la capa que decide: límites en proxy/servicio, autorización por recurso, validación de entrada y salida segura según el caso.","La defensa debe reducir el abuso conservando el comportamiento legítimo. Cambia una condición a la vez para atribuir el resultado."],"workshop":["Implementa el control del caso elegido y documenta el archivo y la decisión técnica.","Reinicia o reconstruye los servicios afectados siguiendo el README.","Repite exactamente el escenario anterior y una petición legítima."],"tests":["Compara los mismos indicadores antes y después.","Prueba un caso límite y comprueba que no se bloquea el usuario legítimo."],"gate":"La defensa controla el caso y las pruebas legítimas siguen pasando.","theory_href":"https://juanperez238421-cpu.github.io/ijr-estadistica-11-2026/seminario-projects/route.html?project=cyber#stage-3","workshop_href":"https://juanperez238421-cpu.github.io/ijr-estadistica-11-2026/seminario-projects/route.html?project=cyber#stage-3"},{"n":4,"title":"4 · Regresión y defensa técnica","goal":"Crea una matriz de pruebas con esperado/obtenido y referencia a evidencia. Reproduce un fallo de la defensa, corrige y vuelve a probar. Entrega README para reconstruir el laboratorio, commits, reporte de causa/control y limitaciones.","deliverable":"Matriz, logs, corrección verificable y demostración técnica.","theory":["Una defensa se evalúa por resultados y límites, no por instalar una herramienta. Los logs sustentan cada conclusión.","La regresión incluye permitido, bloqueado, límite, reinicio y errores de configuración."],"workshop":["Crea una matriz de pruebas con esperado/obtenido y referencia a evidencia.","Reproduce un fallo de la defensa, corrige y vuelve a probar.","Entrega README para reconstruir el laboratorio, commits, reporte de causa/control y limitaciones."],"tests":["Arranca desde una configuración limpia y repite la matriz.","Demuestra en vivo el caso antes/después y explica qué protege y qué queda fuera del alcance."],"gate":"El docente puede reproducir los resultados; los límites y las pruebas pendientes están explícitos.","theory_href":"https://juanperez238421-cpu.github.io/ijr-estadistica-11-2026/seminario-projects/route.html?project=cyber#stage-4","workshop_href":"https://juanperez238421-cpu.github.io/ijr-estadistica-11-2026/seminario-projects/route.html?project=cyber#stage-4"}]'::jsonb
